sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color;
uniform float threshold;
uniform float feather;
uniform float saturation;
uniform float choke;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float3 rgb = float3(src.rgb) / float(src.a);
    float d = distance(rgb, float3(color.rgb)) * choke;
    float keep = 1.0 - smoothstep(threshold, threshold + feather + 0.0001, d);
    float grey = dot(rgb, float3(0.2126, 0.7152, 0.0722));
    float3 other = mix(float3(grey), rgb, saturation);
    return half4(half3(mix(other, rgb, keep)) * src.a, src.a);
}
